<?php require dirname(__DIR__,2).'/app/bootstrap.php';requireAdmin();require dirname(__DIR__,2).'/app/layout.php';$products=db()->query('SELECT * FROM products ORDER BY productId DESC')->fetchAll();$photosByProduct=photosForProducts($products);pageStart('Manage products');?><div class="toolbar"><h1>Manage products</h1><a class="button" href="/admin/edit.php">Add product</a><form action="/admin/logout.php" method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><button class="secondary">Log out</button></form></div><div class="tablewrap"><table><thead><tr><th>ID</th><th>Preview</th><th>Product</th><th>Description</th><th>Price</th><th>Quantity</th><th>Actions</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?= (int)$p['productId'] ?></td><td><?php $first=$photosByProduct[(int)$p['productId']][0]??null;$preview=photoUrl($first ? ($first['thumbnail_key'] ?: $first['photo_key']) : $p['photo_key']);if($preview): ?><img class="admin-list-thumb" src="<?= e($preview) ?>" alt=""><?php endif; ?></td><td><?= e($p['name']) ?></td><td class="admin-description"><?= nl2br(e($p['description'])) ?></td><td>$<?= number_format((float)$p['price'],2) ?></td><td><?= number_format((int)$p['quantity']) ?></td><td><a href="/admin/edit.php?id=<?= (int)$p['productId'] ?>">Edit</a> <form class="inline" method="post" action="/admin/delete.php" onsubmit="return confirm('Delete this product?')"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="id" value="<?= (int)$p['productId'] ?>"><button class="danger">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php pageEnd();
